public class Main {
    static int n;
    static int[] tree;
    static final int INF = (1 << 31) - 1; // 2^31 - 1

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());

        // Initialize segment tree
        int size = 1;
        while (size < n) size <<= 1;
        tree = new int[2 * size];
        Arrays.fill(tree, INF);

        // Build initial tree with INF values
        for (int i = 0; i < n; i++) {
            tree[size + i] = INF;
        }
        for (int i = size - 1; i > 0; i--) {
            tree[i] = Math.min(tree[2 * i], tree[2 * i + 1]);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            int op = Integer.parseInt(st.nextToken());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());

            if (op == 0) {
                // update
                int idx = a;
                int val = b;
                update(size + idx, val);
            } else {
                // find min
                int l = a;
                int r = b;
                sb.append(query(1, 0, size - 1, l, r)).append("\n");
            }
        }
        System.out.print(sb);
    }

    static void update(int pos, int val) {
        tree[pos] = val;
        pos >>= 1;
        while (pos > 0) {
            tree[pos] = Math.min(tree[2 * pos], tree[2 * pos + 1]);
            pos >>= 1;
        }
    }

    static int query(int node, int nodeL, int nodeR, int qL, int qR) {
        if (qL > nodeR || qR < nodeL) return INF;
        if (qL <= nodeL && nodeR <= qR) return tree[node];
        int mid = (nodeL + nodeR) / 2;
        int left = query(node * 2, nodeL, mid, qL, qR);
        int right = query(node * 2 + 1, mid + 1, nodeR, qL, qR);
        return Math.min(left, right);
    }
}

