class SegTree:
    def __init__(self, n):
        self.N = 1
        while self.N < n:
            self.N <<= 1
        self.data = [INF] * (2 * self.N)

    def update(self, i, x):
        i += self.N
        self.data[i] = x
        i >>= 1
        while i:
            self.data[i] = min(self.data[2*i], self.data[2*i+1])
            i >>= 1

    def query(self, l, r):
        l += self.N
        r += self.N
        res = INF
        while l < r:
            if l & 1:
                res = min(res, self.data[l])
                l += 1
            if r & 1:
                r -= 1
                res = min(res, self.data[r])
            l >>= 1
            r >>= 1
        return res

